import React, { useState, useMemo } from 'react';
import { 
  Trash2, Plus, Play, Clock, Calendar, ShieldCheck, Globe, Home, BookOpen, RefreshCw, CheckCircle2, AlertCircle, Settings2, Users
} from 'lucide-react';
import ScheduleGenerator from './ScheduleGenerator';
import GlobalOverview from './GlobalOverview';

// --- HELPER FUNCTIONS (Kept as requested) ---
const formatTime = (timeStr) => {
  if (!timeStr) return "";
  const [h, m] = timeStr.split(':').map(Number);
  const displayH = h % 12 || 12;
  return `${displayH}:${String(m).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`;
};

const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  return `${String(h + hours).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, onDeleteDept, onClearSchedule, globalSchedule = [], allDepartments = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const [generationErrors, setGenerationErrors] = useState([]);
  const [currentVersion, setCurrentVersion] = useState("V1"); // FEATURE 5
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- PREVIEW ENGINE (Kept original logic) ---
  const consolidatedPreview = useMemo(() => {
    const deptData = globalSchedule.filter(s => s.dept_code === deptCode);
    const groups = {};
    const today = new Date().toISOString().split('T')[0];

    deptData.forEach(item => {
      const groupKey = `${item.section}-${item.exam_date}-${item.room}-${item.proctor}`;
      if (!groups[groupKey]) {
        groups[groupKey] = {
          section: item.section, date: item.exam_date, year: item.year_level, room: item.room,
          proctor: item.proctor, status: item.exam_date < today ? 'DONE' : (item.status || 'COMMITTED'),
          startTime: item.start_time, endTime: item.end_time, subs: []
        };
      }
      groups[groupKey].subs.push({ code: item.subject_code, name: item.subject_name, slot: `${formatTime(item.start_time)} - ${formatTime(item.end_time)}`, startTime: item.start_time });
    });

    return Object.values(groups).map(g => ({ ...g, subs: g.subs.sort((a, b) => a.startTime.localeCompare(b.startTime)) }))
                 .sort((a, b) => new Date(a.date) - new Date(b.date) || a.section.localeCompare(b.section));
  }, [globalSchedule, deptCode]);

  const tablesByYearAndDay = useMemo(() => {
    const data = {};
    consolidatedPreview.forEach(item => {
      if (!data[item.year]) data[item.year] = {};
      if (!data[item.year][item.date]) data[item.year][item.date] = [];
      data[item.year][item.date].push(item);
    });
    return data;
  }, [consolidatedPreview]);

  // --- UI STATES (Kept original) ---
  const [examDays, setExamDays] = useState(0); 
  const [examDates, setExamDates] = useState([]);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(0); 
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");
  const [roomType, setRoomType] = useState("Department");

  const globalProctorPool = useMemo(() => allDepartments.flatMap(d => d.proctors), [allDepartments]);
  const globalRoomPool = useMemo(() => allDepartments.flatMap(d => d.rooms), [allDepartments]);

  const handleExamDayChange = (val) => {
    const num = parseInt(val) || 0;
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  // --- CORE GENERATION LOGIC (Kept as is) ---
  const handleGenerateClick = () => {
    setGenerationErrors([]);
    const errors = [];
    const yearSubs = subjects[selectedYear] || [];
    if (yearSubs.length === 0) errors.push({ issue: "No Subjects", resolution: `Add subjects for Year ${selectedYear} first.` });
    if (examDays === 0 || sectionCount === 0) errors.push({ issue: "Config Error", resolution: "Set Exam Days and Section Count." });
    if (examDates.some(d => !d)) errors.push({ issue: "Missing Timeline", resolution: "Assign a date to every exam day." });
    if (errors.length > 0) { setGenerationErrors(errors); return; }

    const shuffled = [...yearSubs].sort(() => Math.random() - 0.5);
    const dailySubs = Array.from({ length: examDays }, () => []);
    shuffled.forEach((s, i) => dailySubs[i % examDays].push(s));
    const finalGeneratedData = [];
    let proctorIndex = 0; let roomIndex = 0;

    for (let d = 0; d < examDays; d++) {
      const dayDate = examDates[d]; const daySubjects = dailySubs[d];
      const duration = daySubjects.length; const endTime = addHours(startTime, duration);
      const isRoomFree = (rNum) => !globalSchedule.some(gs => gs.room === rNum && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time));
      const localRooms = rooms.filter(r => isRoomFree(r.number));
      const otherRooms = globalRoomPool.filter(r => !rooms.find(dr => dr.number === r.number) && isRoomFree(r.number));
      let availableRooms = roomSource === "Department" ? [...localRooms, ...otherRooms] : [...otherRooms, ...localRooms];

      const getAvailableProctors = (pool) => pool.filter(p => dayDate >= p.dayStart && dayDate <= p.dayEnd && startTime >= p.timeStart && endTime <= p.timeEnd && !globalSchedule.some(gs => gs.proctor === p.name && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time)));
      let availableProctors = getAvailableProctors(proctorSource === "Department" ? proctors : globalProctorPool);
      if (availableProctors.length === 0 && proctorSource === "Department") availableProctors = getAvailableProctors(globalProctorPool);

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;
        const selectedRoom = availableRooms[roomIndex % availableRooms.length];
        const selectedProctor = availableProctors[proctorIndex % availableProctors.length];
        if (!selectedRoom || !selectedProctor) { errors.push({ issue: `Resources (Day ${d+1})`, resolution: "Check rooms/staff availability." }); break; }
        daySubjects.forEach((sub, idx) => {
          finalGeneratedData.push({ subject_code: sub.code, subject_name: sub.name, section: sectionID, year_level: selectedYear, dept_code: deptCode, exam_date: dayDate, start_time: addHours(startTime, idx), end_time: addHours(startTime, idx + 1), room: selectedRoom.number, proctor: selectedProctor.name, status: 'ACTIVE' });
        });
        proctorIndex++; roomIndex++;
      }
    }
    if (errors.length > 0) { setGenerationErrors(errors); return; }
    onGenerate(finalGeneratedData, examDates);
    setActiveTab("preview");
  };

  const renderStatusBadge = (status) => {
    if (status === 'ACTIVE') return <span className="flex items-center gap-2 bg-emerald-500 text-white px-4 py-1.5 rounded-full text-[9px] font-black uppercase shadow-lg animate-pulse"><Play size={10} fill="white"/> ACTIVE</span>;
    if (status === 'DONE') return <span className="flex items-center gap-2 bg-slate-800 text-slate-400 px-4 py-1.5 rounded-full text-[9px] font-black uppercase border border-slate-700"><CheckCircle2 size={10}/> DONE</span>;
    return <span className="flex items-center gap-2 bg-blue-50 text-blue-600 px-4 py-1.5 rounded-full text-[9px] font-black uppercase border border-blue-200"><ShieldCheck size={10}/> COMMITTED</span>;
  };

  return (
    <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden mb-16 transition-all hover:shadow-blue-500/5">
      <div className="bg-slate-900 p-10 text-white flex justify-between items-center relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-600 via-emerald-500 to-amber-500"></div>
        <div>
          <div className="flex items-center gap-4">
            <h2 className="text-4xl font-black uppercase italic tracking-tighter leading-none">{deptName}</h2>
            <button onClick={() => onDeleteDept(deptId, deptCode)} className="bg-rose-500/20 hover:bg-rose-500 text-rose-500 hover:text-white p-2 rounded-xl transition-all"><Trash2 size={20}/></button>
          </div>
          <p className="text-blue-400 text-[10px] font-black uppercase tracking-[0.4em] mt-3 flex items-center gap-2"><Settings2 size={12}/> Departmental Workspace Engine</p>
        </div>
        <div className="flex gap-4">
            <div className="bg-white/5 backdrop-blur-md px-6 py-3 rounded-[1.5rem] border border-white/10 text-center min-w-[80px]">
                <span className="block text-[8px] font-black text-blue-400 uppercase tracking-widest mb-1 text-center">Staff</span>
                <span className="text-2xl font-black">{proctors.length}</span>
            </div>
            <div className="bg-white/5 backdrop-blur-md px-6 py-3 rounded-[1.5rem] border border-white/10 text-center min-w-[80px]">
                <span className="block text-[8px] font-black text-emerald-400 uppercase tracking-widest mb-1">Rooms</span>
                <span className="text-2xl font-black">{rooms.length}</span>
            </div>
        </div>
      </div>

      <div className="flex bg-slate-50/50 p-3 gap-2 border-b border-slate-100">
        {['subjects', 'proctors', 'rooms', 'generate', 'preview'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-[0.2em] rounded-2xl transition-all duration-300 ${activeTab === t ? 'bg-white shadow-xl text-blue-600 scale-[1.02] border border-slate-100' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'}`}>
            {t} {t === 'preview' && consolidatedPreview.length > 0 && `(${consolidatedPreview.length})`}
          </button>
        ))}
      </div>

      <div className="p-12">
        {activeTab === 'subjects' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-2">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 shadow-inner">
              <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-400 uppercase ml-2">Year Level</label>
                  <select className="w-full p-4 rounded-2xl text-xs font-black bg-white border-2 border-slate-100 outline-none focus:border-blue-500 appearance-none" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                      {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year Level {y}</option>)}
                  </select>
              </div>
              <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-400 uppercase ml-2">Subject Code</label>
                  <input id={`sC-${deptId}`} placeholder="e.g. CS101" className="w-full p-4 rounded-2xl text-xs font-black bg-white border-2 border-slate-100 outline-none focus:border-blue-500" />
              </div>
              <div className="space-y-2 md:col-span-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase ml-2">Description</label>
                  <input id={`sN-${deptId}`} placeholder="Full Name" className="w-full p-4 rounded-2xl text-xs font-black bg-white border-2 border-slate-100 outline-none focus:border-blue-500" />
              </div>
              <div className="pt-6">
                  <button onClick={() => {
                    const c = document.getElementById(`sC-${deptId}`).value;
                    const n = document.getElementById(`sN-${deptId}`).value;
                    if (c && n) {
                      onUpdate('subjects', { ...subjects, [selectedYear]: [...(subjects[selectedYear] || []), { code: c.toUpperCase(), name: n }] });
                      document.getElementById(`sC-${deptId}`).value = ''; document.getElementById(`sN-${deptId}`).value = '';
                    }
                  }} className="w-full h-full bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg active:scale-95 flex items-center justify-center gap-2">
                      <Plus size={14}/> Add Item
                  </button>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto pr-4 custom-scrollbar">
              {subjects[selectedYear]?.map((s, i) => (
                <div key={i} className="group flex justify-between p-6 bg-white border-2 border-slate-50 rounded-3xl items-center transition-all hover:border-blue-100 hover:shadow-lg">
                  <div className="flex items-center gap-4">
                    <div className="bg-blue-50 p-3 rounded-xl text-blue-600 font-black text-xs">{s.code}</div>
                    <span className="text-slate-600 font-black text-xs uppercase tracking-tight">{s.name}</span>
                  </div>
                  <button onClick={() => onUpdate('subjects', { ...subjects, [selectedYear]: subjects[selectedYear].filter((_, idx) => idx !== i) })}>
                    <Trash2 size={18} className="text-slate-200 group-hover:text-rose-500 transition-colors" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'proctors' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-2">
            <div className="bg-emerald-50/50 p-10 rounded-[3rem] border border-emerald-100 space-y-8 shadow-inner">
              <div className="flex flex-col md:flex-row gap-6">
                <div className="flex-1 space-y-2">
                  <label className="text-[9px] font-black text-emerald-600 uppercase ml-4">Full Legal Name</label>
                  <input value={pName} onChange={e => setPName(e.target.value)} placeholder="ENTER STAFF NAME" className="w-full p-5 rounded-3xl text-xs font-black border-2 border-emerald-100 outline-none focus:border-emerald-500" />
                </div>
                <div className="md:pt-6">
                  <button onClick={() => {
                    if (pName && pDayStart && pDayEnd && pTimeStart && pTimeEnd) {
                      onUpdate('proctors', [...proctors, { id: Date.now(), name: pName.toUpperCase(), dayStart: pDayStart, dayEnd: pDayEnd, timeStart: pTimeStart, timeEnd: pTimeEnd }]);
                      setPName("");
                    }
                  }} className="h-full px-12 bg-emerald-600 text-white rounded-3xl font-black text-[10px] uppercase shadow-lg active:scale-95">Register Staff</button>
                </div>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                <div className="space-y-2"><label className="text-[9px] font-black uppercase text-emerald-500 ml-4">Start Date</label><input type="date" value={pDayStart} onChange={e => setPDayStart(e.target.value)} className="w-full p-4 rounded-2xl text-[10px] font-black border-2 border-emerald-50" /></div>
                <div className="space-y-2"><label className="text-[9px] font-black uppercase text-emerald-500 ml-4">End Date</label><input type="date" value={pDayEnd} onChange={e => setPDayEnd(e.target.value)} className="w-full p-4 rounded-2xl text-[10px] font-black border-2 border-emerald-50" /></div>
                <div className="space-y-2"><label className="text-[9px] font-black uppercase text-emerald-500 ml-4">Shift Start</label><input type="time" value={pTimeStart} onChange={e => setPTimeStart(e.target.value)} className="w-full p-4 rounded-2xl text-[10px] font-black border-2 border-emerald-50" /></div>
                <div className="space-y-2"><label className="text-[9px] font-black uppercase text-emerald-500 ml-4">Shift End</label><input type="time" value={pTimeEnd} onChange={e => setPTimeEnd(e.target.value)} className="w-full p-4 rounded-2xl text-[10px] font-black border-2 border-emerald-50" /></div>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto pr-4 custom-scrollbar">
              {proctors.map(p => (
                <div key={p.id} className="p-6 border-2 border-slate-50 rounded-[2.5rem] flex justify-between items-center bg-white hover:border-emerald-100 hover:shadow-lg group">
                  <div>
                    <p className="font-black text-xs uppercase text-slate-800 flex items-center gap-2"><Users size={14} className="text-emerald-500"/> {p.name}</p>
                    <p className="text-[9px] text-slate-400 font-black uppercase tracking-tighter mt-1 italic">{p.dayStart} / {p.dayEnd} • {formatTime(p.timeStart)} - {formatTime(p.timeEnd)}</p>
                  </div>
                  <Trash2 size={18} className="text-slate-100 group-hover:text-rose-500 cursor-pointer transition-colors" onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))} />
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'rooms' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-2">
            <div className="flex flex-col md:flex-row gap-4 bg-amber-50/50 p-8 rounded-[3rem] border border-amber-100 shadow-inner">
              <input value={roomNum} onChange={e => setRoomNum(e.target.value)} placeholder="ROOM NO. OR HALL NAME" className="flex-1 p-5 rounded-3xl text-xs font-black border-2 border-amber-50 outline-none focus:border-amber-500" />
              <select value={roomType} onChange={e => setRoomType(e.target.value)} className="bg-white px-8 rounded-3xl font-black text-[10px] uppercase outline-none shadow-sm border-2 border-amber-50 appearance-none">
                <option value="Department">Internal Resource</option>
                <option value="Global">Global Pool</option>
              </select>
              <button onClick={() => { if (roomNum) { onUpdate('rooms', [...rooms, { id: Date.now(), number: roomNum.toUpperCase(), type: roomType }]); setRoomNum(""); } }} className="bg-amber-600 text-white px-10 py-5 rounded-3xl font-black uppercase text-[10px] shadow-lg active:scale-95">Add Room</button>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
              {rooms.map(r => (
                <div key={r.id} className="p-8 bg-white border-2 border-slate-50 rounded-[3rem] text-center relative group shadow-sm hover:border-amber-200 transition-all">
                  <span className="font-black text-2xl text-slate-800 tracking-tighter">{r.number}</span>
                  <span className={`block text-[8px] font-black uppercase mt-2 tracking-widest ${r.type === 'Global' ? 'text-blue-500' : 'text-amber-500'}`}>{r.type} Source</span>
                  <button className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 text-rose-500 transition-opacity" onClick={() => onUpdate('rooms', rooms.filter(item => item.id !== r.id))}><Trash2 size={16}/></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'generate' && (
          <ScheduleGenerator 
            examDays={examDays} examDates={examDates} setExamDates={setExamDates} 
            handleExamDayChange={handleExamDayChange} startTime={startTime} setStartTime={setStartTime}
            selectedYear={selectedYear} setSelectedYear={setSelectedYear} sectionCount={sectionCount}
            setSectionCount={setSectionCount} proctorSource={proctorSource} setProctorSource={setProctorSource}
            roomSource={roomSource} setRoomSource={setRoomSource} onGenerate={handleGenerateClick}
            generationErrors={generationErrors} deptCode={deptCode} globalSchedule={globalSchedule}
          />
        )}

        {activeTab === 'preview' && (
          <div className="space-y-10 animate-in fade-in duration-500">
            <div className="flex justify-between items-end border-b-2 border-slate-100 pb-8 px-4">
              <div>
                <h3 className="text-4xl font-black uppercase text-slate-900 tracking-tighter">Master <span className="text-blue-600">Draft</span></h3>
                <div className="flex gap-2 mt-2">
                    {["V1", "V2", "V3"].map(v => (
                        <button key={v} onClick={() => setCurrentVersion(v)} className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase transition-all ${currentVersion === v ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>Draft {v}</button>
                    ))}
                </div>
              </div>
              <button onClick={() => onClearSchedule(deptCode)} className="flex items-center gap-3 bg-white border-2 border-rose-100 text-rose-500 px-8 py-4 rounded-[1.5rem] font-black text-[10px] uppercase hover:bg-rose-50 transition-all active:scale-95"><Trash2 size={18}/> Wipe All Drafts</button>
            </div>

            <GlobalOverview tablesByYearAndDay={tablesByYearAndDay} />

            <div className="grid grid-cols-1 gap-10 mt-16">
                <h4 className="text-2xl font-black text-slate-900 uppercase tracking-tighter px-4">Detailed View & Management</h4>
                {consolidatedPreview.map((row, i) => (
                    <div key={i} className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden flex flex-col md:flex-row hover:border-blue-300 transition-all hover:shadow-2xl group relative">
                        <div className="absolute top-6 right-10 flex gap-4 z-20 items-center">
                            {renderStatusBadge(row.status)}
                            {/* FEATURE 2: Swap Button */}
                            <button className="bg-amber-100 text-amber-600 p-3 rounded-xl hover:bg-amber-600 hover:text-white transition-all shadow-sm opacity-0 group-hover:opacity-100"><RefreshCw size={16} /></button>
                            <button onClick={() => onClearSchedule(deptCode, row.year, row.section, row.date)} className="bg-rose-100 text-rose-600 p-3 rounded-xl hover:bg-rose-600 hover:text-white transition-all shadow-sm"><Trash2 size={16} /></button>
                        </div>

                        <div className={`p-10 md:w-80 flex flex-col justify-between text-white border-r-8 transition-all duration-500 ${row.status === 'ACTIVE' ? 'bg-slate-900 border-emerald-500' : 'bg-slate-800 border-blue-600'}`}>
                            <div><span className="text-blue-400 font-black text-[10px] uppercase tracking-[0.3em]">Year {row.year}</span><h5 className="text-5xl font-black tracking-tighter mt-2">{row.section}</h5></div>
                            <div className="mt-8 space-y-4">
                                <div className="flex items-center gap-3 text-[11px] font-black uppercase"><Calendar size={16} className="text-blue-400"/> {row.date}</div>
                                <div className="flex items-center gap-3 text-[11px] font-black uppercase"><Clock size={16} className="text-blue-400"/> {formatTime(row.startTime)} - {formatTime(row.endTime)}</div>
                            </div>
                            <div className="mt-10 pt-8 border-t border-white/10 space-y-3">
                                <div className="bg-blue-600 px-4 py-2 rounded-xl text-[10px] font-black flex justify-between items-center"><span>ROOM</span><span>{row.room}</span></div>
                                <div className="bg-white/10 px-4 py-2 rounded-xl text-[10px] font-black flex justify-between items-center"><span>PROCTOR</span><span className="truncate ml-2">{row.proctor}</span></div>
                            </div>
                        </div>

                        <div className="flex-1 p-10 bg-slate-50/30">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                {row.subs.map((s, idx) => (
                                    <div key={idx} className="bg-white p-6 rounded-3xl border-2 border-white shadow-sm group-hover:border-blue-100 transition-all flex flex-col justify-between hover:shadow-md">
                                        <div className="flex justify-between items-start"><span className="text-sm font-black text-blue-600">{s.code}</span><span className="text-[9px] font-black text-slate-400 uppercase italic">{s.slot}</span></div>
                                        <p className="text-[11px] font-black text-slate-800 uppercase mt-4 leading-snug">{s.name}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
